<script lang="ts">
 import {onMount} from 'svelte';
 import {api} from './api';
 import type {Row} from './types';
 let data:Row|null=$state(null),busy=$state(false),error=$state(''),notice=$state(''),password=$state(''),section=$state('Templates');
 let edit:Row|null=$state(null),recipient:Row|null=$state(null),testPhone=$state(''),consent=$state(false);
 let enabled=$state(false),hour=$state(9),cap=$state(1000);
 const labels:Record<string,string>={assignment:'New work assigned',update:'Work updated',daily:'Daily pending work',renewal:'Document renewal',test:'Connection test'};
 const preview=(body:string)=>['Ansu','PO EXAMPLE · Sampling','2 pieces pending; due 10 October 2026','https://erp.eurosuitsmfg.in/sampling'].reduce((s,v,i)=>s.replaceAll('{{'+(i+1)+'}}',v),body);
 async function load(){data=await api('/developer/whatsapp');enabled=data!.settings.enabled;hour=data!.settings.reminder_hour;cap=data!.settings.daily_cap;}
 onMount(()=>{load().catch(e=>error=e.message)});
 async function run(body:Row){if(busy)return;busy=true;error='';notice='';try{await api('/developer/whatsapp',{...body,password});password='';edit=null;recipient=null;await load();notice=body.action==='test'?'Test queued. Refresh delivery history after about one minute.':body.action==='submit'?'Submitted to Meta. Sync status to check approval.':'Changes saved.'}catch(e){error=(e as Error).message}finally{busy=false}}
 async function refresh(){if(busy)return;busy=true;try{await load()}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<section class="wa-page">
 <header class="wa-heading"><div><p class="eyebrow">EURO SUITS · NOTIFICATIONS</p><h1>WhatsApp control centre</h1><p>Work alerts, daily reminders and delivery checks.</p></div><button class="button secondary" disabled={busy} onclick={refresh}>Refresh</button></header>
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p class="company-notice" role="status">{notice}</p>{/if}
 {#if data}
 <div class="wa-stats"><article><small>Connection</small><strong>{data.configured?'Credentials configured':'Setup required'}</strong></article><article><small>Automatic messages</small><strong>{data.settings.enabled?'Enabled':'Paused'}</strong></article><article><small>Daily summary</small><strong>{String(data.settings.reminder_hour).padStart(2,'0')}:00 IST</strong></article><article><small>Enabled recipients</small><strong>{data.recipients.filter((r:Row)=>r.enabled).length}</strong></article></div>
 {#if !data.configured}<p class="company-warning">Meta sender registration and server credentials are required before sending. Preview and edit your templates below.</p>{/if}
 <nav class="wa-tabs" aria-label="WhatsApp sections">{#each ['Templates','Recipients','Delivery history','Settings & test'] as value}<button class:active={section===value} onclick={()=>section=value}>{value}</button>{/each}</nav>
 <div class="wa-confirm"><label>Your developer password<input type="password" autocomplete="current-password" bind:value={password} placeholder="Required only when saving or sending" maxlength="128"/></label><p>Changes require a recent developer email verification. Your password is cleared after each successful action.</p></div>
 {#if section==='Templates'}
 <p>Each template has four values: employee name, work reference, current details and dashboard link. Edited templates must be approved again. Use a new Meta template name for a revised version.</p>
 <div class="wa-grid">{#each data.templates as t}<article class="wa-card"><header><h2>{labels[t.kind]}</h2><span class:approved={t.status==='APPROVED'}>{t.status}</span></header><p class="wa-meta">{t.name} · {t.language}</p><div class="wa-chat"><strong>EURO SUITS</strong><p>{preview(t.body)}</p></div><div class="wa-actions"><button class="button secondary" disabled={busy} onclick={()=>edit={...t}}>Edit template</button><button class="button secondary" disabled={busy||!data?.configured} onclick={()=>run({action:'sync',kind:t.kind})}>Sync status</button><button class="button primary" disabled={busy||!data?.configured||t.status!=='DRAFT'||!password} onclick={()=>run({action:'submit',kind:t.kind})}>Submit to Meta</button></div></article>{/each}</div>
 {#if edit}<form class="wa-editor" onsubmit={e=>{e.preventDefault();if(edit)run({action:'template',kind:edit.kind,name:edit.name,language:edit.language,body:edit.body,version:edit.version})}}><h2>Edit {labels[edit.kind]}</h2><label>Meta template name<input bind:value={edit.name} required pattern={'[a-z][a-z0-9_]{2,100}'}/></label><label>Language code<input bind:value={edit.language} required/></label><label>Message<textarea bind:value={edit.body} rows="5" maxlength="1024" required></textarea></label><p>Keep {'{{1}}'}, {'{{2}}'}, {'{{3}}'}, {'{{4}}'} once each, in order.</p><div class="wa-chat">{preview(edit.body)}</div><div class="wa-actions"><button class="button secondary" type="button" onclick={()=>edit=null}>Cancel</button><button class="button primary" disabled={busy||!password}>Save draft</button></div></form>{/if}
 {:else if section==='Recipients'}
 <p>Numbers come from Accounts → Account settings. Enable only employees who agreed to receive work notifications. A STOP reply disables future notifications once Meta webhooks are connected.</p>
 <div class="table-wrap"><table><thead><tr><th>Employee</th><th>WhatsApp number</th><th>Status</th><th>Action</th></tr></thead><tbody>{#each data.recipients as r}<tr><td><strong>{r.name}</strong><br/>{r.username}</td><td>{r.phone||'Add number in Accounts'}</td><td>{!r.active?'Account disabled':r.enabled?'Enabled':'Off'}</td><td><button class="button secondary" disabled={busy||!r.active} onclick={()=>recipient={...r}}>Manage</button></td></tr>{/each}</tbody></table></div>
 {#if recipient}<form class="wa-editor" onsubmit={e=>{e.preventDefault();if(recipient)run({action:'recipient',user_id:recipient.id,enabled:recipient.enabled,consent_note:recipient.consent_note})}}><h2>{recipient.name}</h2><label class="wa-check"><input type="checkbox" bind:checked={recipient.enabled}/>Enable WhatsApp work notifications</label><label>Consent record<textarea bind:value={recipient.consent_note} rows="3" maxlength="500" required={recipient.enabled} placeholder="When and how this employee agreed"></textarea></label><div class="wa-actions"><button type="button" class="button secondary" onclick={()=>recipient=null}>Cancel</button><button class="button primary" disabled={busy||!password}>Save recipient</button></div></form>{/if}
 {:else if section==='Delivery history'}
 <p>Accepted means Meta accepted the request. Delivered and Read require signed Meta webhooks. Unknown results are never automatically retried.</p>
 <div class="table-wrap"><table><thead><tr><th>Time</th><th>User / number</th><th>Type</th><th>Delivery</th><th>Details</th></tr></thead><tbody>{#each data.messages as m}<tr><td>{new Date(m.created_at).toLocaleString()}</td><td>{m.username}<br/>{m.phone}</td><td>{labels[m.kind]}</td><td><strong>{m.status}</strong></td><td>{m.error||m.meta_id||'Waiting for processing'}</td></tr>{:else}<tr><td colspan="5">No WhatsApp messages sent yet.</td></tr>{/each}</tbody></table></div>
 {:else}
 <div class="wa-grid"><form class="wa-card" onsubmit={e=>{e.preventDefault();run({action:'settings',enabled,reminder_hour:hour,daily_cap:cap,version:data!.settings.version})}}><h2>Automatic notifications</h2><label class="wa-check"><input type="checkbox" bind:checked={enabled}/>Enable automatic work alerts</label><label>Daily summary hour (India time)<input type="number" min="0" max="23" bind:value={hour} required/></label><label>Maximum message attempts per day<input type="number" min="1" max="10000" bind:value={cap} required/></label><p>Assignment and status changes are checked every minute. One daily pending-work summary per employee. Enabling also picks up current pending assignments.</p><button class="button primary" disabled={busy||!password}>Save settings</button></form>
 <form class="wa-card" onsubmit={e=>{e.preventDefault();run({action:'test',phone:testPhone,consent_confirmed:consent})}}><h2>Send a connection test</h2><label>Recipient WhatsApp number<input bind:value={testPhone} required placeholder="+91…"/></label><label class="wa-check"><input type="checkbox" bind:checked={consent}/>This recipient requested the test</label><p>Uses the approved connection-test template. No company records are included. Limited to three tests per developer per hour.</p><button class="button primary" disabled={busy||!password||!consent||!data.configured}>Send test message</button></form></div>
 <section class="wa-card"><h2>Meta connection</h2><p>Webhook: <code>{data.webhook_url}</code></p><p>Phone ID: {data.phone_id||'Not configured'} · Business account: {data.business_account_id||'Not configured'}</p><p>Access tokens, app secret and verification token stay on the server. They are never displayed in this page.</p></section>
 {/if}
 {:else}<p role="status">Loading WhatsApp workspace…</p>{/if}
</section>
<style>
 .wa-page{color:#172b3e}.wa-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.wa-heading h1{font-size:28px;margin:5px 0}.wa-heading p{margin:5px 0}.wa-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.wa-stats article,.wa-card,.wa-editor,.wa-confirm{background:white;border:1px solid #d4e0e6;border-radius:12px;padding:22px;margin-bottom:20px}.wa-stats small{display:block;margin-bottom:10px}.wa-stats strong{font-size:19px}.wa-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 20px}.wa-tabs button{padding:12px 18px;border:1px solid #b4c6d2;border-radius:8px;background:#edf4f8;color:#172b3e;font-weight:700}.wa-tabs .active{background:#172b3e;color:white}.wa-confirm{display:flex;gap:24px;align-items:center}.wa-confirm label{flex:1}.wa-confirm p{flex:1;font-size:13px}.wa-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.wa-card header{display:flex;justify-content:space-between;align-items:center;gap:12px}.wa-card h2,.wa-editor h2{font-size:18px;margin:0 0 12px}.wa-card header span{font-size:11px;background:#fff2d8;padding:6px 8px;border-radius:6px;font-weight:800}.wa-card header span.approved{background:#daf0e5;color:#186041}.wa-meta{font-size:12px;overflow-wrap:anywhere}.wa-chat{background:#e7f4ed;border:1px solid #bfdaca;border-radius:4px 14px 14px;padding:18px;line-height:1.65;font-size:15px;white-space:pre-wrap;overflow-wrap:anywhere}.wa-chat strong{font-size:11px;letter-spacing:2px;color:#276a52}.wa-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.wa-page label{display:grid;gap:8px;font-weight:700;margin-bottom:16px}.wa-page input:not([type=checkbox]),.wa-page textarea{width:100%;padding:12px;background:#edf4fa;border:1px solid #b6cbd9;border-radius:7px;font:inherit;color:#142331}.wa-page .wa-check{display:flex;align-items:center;gap:10px}.wa-editor{border:2px solid #47788e}.wa-page table{width:100%;background:white}.wa-page td{overflow-wrap:anywhere}.wa-page code{overflow-wrap:anywhere}.wa-page p{line-height:1.6}@media(max-width:950px){.wa-stats,.wa-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.wa-confirm{display:block}}@media(max-width:600px){.wa-grid,.wa-stats{grid-template-columns:1fr}.wa-heading{align-items:flex-start}.wa-card{padding:16px}}
</style>
